pub fn get_partition_byte_range(&self, partition_number: u32) -> Result<RangeInclusive<u64>> {
    if partition_number == 0 || partition_number > self.partitions.len() as u32 {
        return Err(Result::Err(InvalidPartitionNumber(partition_number)));
    }

    let partition = &self.partitions[partition_number as usize - 1];

    if !partition.is_used() {
        return Err(Result::Err(InvalidPartitionBoundaries));
    }

    if partition.ending_lba < partition.starting_lba {
        return Err(Result::Err(InvalidPartitionBoundaries));
    }

    let start_byte = partition.starting_lba * self.sector_size;
    let end_byte = partition.ending_lba * self.sector_size;

    Ok(start_byte..=end_byte)
}

